import{_ as e,C as i,c as a,o,j as t,b as r,a0 as l,a as n,w as s,G as u,a1 as c}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Costruire la tua routine pre-tiro","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/mental-strength/pre-shot-routine.md","filePath":"it/education/mental-strength/pre-shot-routine.md"}');const p=e({name:"it/education/mental-strength/pre-shot-routine.md"},[["render",function(e,d,p,h,m,g){const z=i("Mermaid");return o(),a("div",null,[d[1]||(d[1]=t("h1",{id:"costruire-la-tua-routine-pre-tiro",tabindex:"-1"},[n("Costruire la tua routine pre-tiro "),t("a",{class:"header-anchor",href:"#costruire-la-tua-routine-pre-tiro","aria-label":'Permalink to "Costruire la tua routine pre-tiro"'},"​")],-1)),d[2]||(d[2]=t("p",null,"La routine pre-tiro è uno degli strumenti più potenti per la tua performance mentale. È una sequenza coerente di azioni che ti prepara a ogni tiro e innesca il tuo stato di prestazione migliore.",-1)),d[3]||(d[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"La grande idea"),t("p",null,[t("strong",null,"La tua routine è la porta d'accesso alla zona."),n(' Una routine pre-tiro coerente invia al cervello un segnale: "È il momento di eseguire". Ripetendola, diventa un innesco automatico per prestazioni ottimali.')])],-1)),(o(),r(c,null,{default:s(()=>[u(z,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BAvvia%20la%20routine%5D%20--%3E%20B%5BIl%20cervello%20riconosce%20lo%20schema%5D%0A%20%20%20%20B%20--%3E%20C%5BCambio%20di%20stato%20automatico%5D%0A%20%20%20%20C%20--%3E%20D%5BModalit%C3%A0%20di%20esecuzione%5D%0A%20%20%20%20D%20--%3E%20E%5BMassima%20prestazione%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...d[0]||(d[0]=[n(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=l('<h2 id="perche-le-routine-funzionano" tabindex="-1">Perché le routine funzionano <a class="header-anchor" href="#perche-le-routine-funzionano" aria-label="Permalink to &quot;Perché le routine funzionano&quot;">​</a></h2><h3 id="la-coerenza-crea-fiducia" tabindex="-1">La coerenza crea fiducia <a class="header-anchor" href="#la-coerenza-crea-fiducia" aria-label="Permalink to &quot;La coerenza crea fiducia&quot;">​</a></h3><p>Quando fai sempre la stessa cosa, elimini le variabili. Il tuo corpo sa cosa sta per succedere. Questo crea un senso di controllo e familiarità, anche in situazioni insolite.</p><h3 id="stati-di-attivazione-delle-routine" tabindex="-1">Stati di attivazione delle routine <a class="header-anchor" href="#stati-di-attivazione-delle-routine" aria-label="Permalink to &quot;Stati di attivazione delle routine&quot;">​</a></h3><p>Con la ripetizione, la routine diventa legata al tuo stato di prestazione. Avviare la routine innesca automaticamente il passaggio mentale alla modalità di esecuzione.</p><h3 id="le-routine-bloccano-le-distrazioni" tabindex="-1">Le routine bloccano le distrazioni <a class="header-anchor" href="#le-routine-bloccano-le-distrazioni" aria-label="Permalink to &quot;Le routine bloccano le distrazioni&quot;">​</a></h3><p>Una routine ti dà qualcosa su cui concentrarti. Non c&#39;è spazio per preoccuparti del punteggio, del pubblico o di cosa potrebbe succedere.</p><h3 id="le-routine-gestiscono-l-39-eccitazione" tabindex="-1">Le routine gestiscono l&#39;eccitazione <a class="header-anchor" href="#le-routine-gestiscono-l-39-eccitazione" aria-label="Permalink to &quot;Le routine gestiscono l&amp;#39;eccitazione&quot;">​</a></h3><p>Una routine ben strutturata aiuta a regolare il tuo livello di energia, calmandoti se sei troppo eccitato e concentrandoti se sei a terra.</p><h2 id="elementi-di-una-routine-efficace" tabindex="-1">Elementi di una routine efficace <a class="header-anchor" href="#elementi-di-una-routine-efficace" aria-label="Permalink to &quot;Elementi di una routine efficace&quot;">​</a></h2><h3 id="fase-1-valutazione-fuori-dal-cerchio" tabindex="-1">Fase 1: Valutazione (fuori dal cerchio) <a class="header-anchor" href="#fase-1-valutazione-fuori-dal-cerchio" aria-label="Permalink to &quot;Fase 1: Valutazione (fuori dal cerchio)&quot;">​</a></h3><p>Prima di entrare, raccogli informazioni:</p><ul><li>Leggere il terreno (pendenze, ostacoli, superficie)</li><li>Valutare la situazione (punteggio, posizione delle bocce)</li><li>Scegli il tuo bersaglio e il punto di atterraggio</li><li>Decidi il tipo di lancio (punta, tira, pallonetto, rotola)</li></ul><p><strong>È qui che avviene il pensiero.</strong> Prenditi il tuo tempo.</p><h3 id="fase-2-transizione-entrare-nel-cerchio" tabindex="-1">Fase 2: Transizione (Entrare nel Cerchio) <a class="header-anchor" href="#fase-2-transizione-entrare-nel-cerchio" aria-label="Permalink to &quot;Fase 2: Transizione (Entrare nel Cerchio)&quot;">​</a></h3><p>Il passaggio dal pensare all&#39;agire:</p><ul><li>Azione fisica (mettersi in cerchio in modo coerente)</li><li>Segnale mentale (una parola o una frase che segnala la &quot;modalità di esecuzione&quot;)</li><li>Respiro (un respiro consapevole per centrarti)</li></ul><p><strong>Questo è il passaggio.</strong> L&#39;analisi si ferma qui.</p><h3 id="fase-3-preparazione-nel-cerchio" tabindex="-1">Fase 3: Preparazione (nel cerchio) <a class="header-anchor" href="#fase-3-preparazione-nel-cerchio" aria-label="Permalink to &quot;Fase 3: Preparazione (nel cerchio)&quot;">​</a></h3><p>Prepara il tuo corpo:</p><ul><li>Posizione coerente (la stessa ogni volta)</li><li>Controllo della presa (sentire la boccia)</li><li>Allineamento al bersaglio</li><li>Innesco fisico (un piccolo movimento che è tuo)</li></ul><h3 id="fase-4-visualizzazione-breve" tabindex="-1">Fase 4: Visualizzazione (Breve) <a class="header-anchor" href="#fase-4-visualizzazione-breve" aria-label="Permalink to &quot;Fase 4: Visualizzazione (Breve)&quot;">​</a></h3><p>Guarda il lancio prima di realizzarlo:</p><ul><li>Immagina il percorso della palla (2-3 secondi al massimo)</li><li>Senti il lancio riuscito</li><li>Connettiti visivamente con il tuo target</li></ul><h3 id="fase-5-esecuzione" tabindex="-1">Fase 5: Esecuzione <a class="header-anchor" href="#fase-5-esecuzione" aria-label="Permalink to &quot;Fase 5: Esecuzione&quot;">​</a></h3><p>Effettua il lancio:</p><ul><li>Messa a fuoco esterna (solo bersaglio)</li><li>Fidati del tuo corpo</li><li>Rilasciare senza esitazione</li><li>Seguire con naturalezza</li></ul><h2 id="costruire-la-tua-routine-personale" tabindex="-1">Costruire la tua routine personale <a class="header-anchor" href="#costruire-la-tua-routine-personale" aria-label="Permalink to &quot;Costruire la tua routine personale&quot;">​</a></h2><h3 id="fase-1-osserva-cio-che-fai-gia" tabindex="-1">Fase 1: osserva ciò che fai già <a class="header-anchor" href="#fase-1-osserva-cio-che-fai-gia" aria-label="Permalink to &quot;Fase 1: osserva ciò che fai già&quot;">​</a></h3><p>Probabilmente hai già una certa routine. Nota:</p><ul><li>Cosa fai prima di un buon lancio?</li><li>Cosa ti sembra naturale?</li><li>Cosa ti aiuta a concentrarti?</li></ul><h3 id="fase-2-progetta-la-tua-routine" tabindex="-1">Fase 2: Progetta la tua routine <a class="header-anchor" href="#fase-2-progetta-la-tua-routine" aria-label="Permalink to &quot;Fase 2: Progetta la tua routine&quot;">​</a></h3><p>Crea una sequenza che includa:</p><ul><li>[ ] Fase di valutazione</li><li>[ ] Momento di transizione chiaro</li><li>[ ] Configurazione fisica coerente</li><li>[ ] Breve visualizzazione</li><li>[ ] Trigger di esecuzione</li></ul><h3 id="passaggio-3-scrivilo" tabindex="-1">Passaggio 3: scrivilo <a class="header-anchor" href="#passaggio-3-scrivilo" aria-label="Permalink to &quot;Passaggio 3: scrivilo&quot;">​</a></h3><p>Sii specifico. Esempio:</p><ol><li><strong>Valutazione:</strong> Leggi il terreno, scegli il punto di atterraggio</li><li><strong>Transizione:</strong> Entra in cerchio con il piede sinistro per primo, pronuncia &quot;fiducia&quot;</li><li><strong>Preparazione:</strong> Piedi alla larghezza delle spalle, controllo della presa, allineamento delle spalle</li><li><strong>Visualizza:</strong> Guarda il percorso, senti la liberazione</li><li><strong>Esegui:</strong> Occhi sul bersaglio, lancia</li></ol><h3 id="fase-4-pratica-religiosamente" tabindex="-1">Fase 4: Pratica religiosamente <a class="header-anchor" href="#fase-4-pratica-religiosamente" aria-label="Permalink to &quot;Fase 4: Pratica religiosamente&quot;">​</a></h3><p>Utilizza la tua routine per OGNI lancio in allenamento:</p><ul><li>Lanci facili</li><li>Lanci difficili</li><li>Quando sei stanco</li><li>Quando sei fresco</li></ul><p>La routine deve diventare automatica.</p><h3 id="fase-5-perfezionare-nel-tempo" tabindex="-1">Fase 5: perfezionare nel tempo <a class="header-anchor" href="#fase-5-perfezionare-nel-tempo" aria-label="Permalink to &quot;Fase 5: perfezionare nel tempo&quot;">​</a></h3><p>La tua routine evolverà. Nota cosa funziona e adattala. Ma non modificarla durante la gara, solo tra un evento e l&#39;altro.</p><h2 id="tempistica-di-routine" tabindex="-1">Tempistica di routine <a class="header-anchor" href="#tempistica-di-routine" aria-label="Permalink to &quot;Tempistica di routine&quot;">​</a></h2><p>La tua routine dovrebbe durare un periodo di tempo costante:</p><ul><li>Troppo veloce: stai correndo, non sei adeguatamente preparato</li><li>Troppo lento: stai pensando troppo e perdi il flusso</li><li>Giusto: abbastanza tempo per prepararsi, non così tanto da pensare troppo</li></ul><p><strong>Tempistica tipica:</strong></p><ul><li>Valutazione: 5-10 secondi</li><li>Transizione + Impostazione: 3-5 secondi</li><li>Visualizzazione + Esecuzione: 3-5 secondi</li><li><strong>Totale: 10-20 secondi</strong></li></ul><h2 id="errori-comuni-di-routine" tabindex="-1">Errori comuni di routine <a class="header-anchor" href="#errori-comuni-di-routine" aria-label="Permalink to &quot;Errori comuni di routine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Errore</th><th>Problema</th><th>Soluzione</th></tr></thead><tbody><tr><td>Saltare in pratica</td><td>La routine non è automatica</td><td>Usalo ad ogni singolo lancio</td></tr><tr><td>Troppo complicato</td><td>Difficile da ricordare sotto pressione</td><td>Semplificare all&#39;essenziale</td></tr><tr><td>Pensare durante l&#39;esecuzione</td><td>Interrompe le prestazioni automatiche</td><td>Chiaro punto di transizione</td></tr><tr><td>Tempi incoerenti</td><td>Crea incertezza</td><td>Esercitati con un ritmo costante</td></tr><tr><td>Cambiare a metà competizione</td><td>Introduce il dubbio</td><td>Attieniti a ciò che conosci</td></tr></tbody></table><h2 id="risoluzione-dei-problemi-di-routine" tabindex="-1">Risoluzione dei problemi di routine <a class="header-anchor" href="#risoluzione-dei-problemi-di-routine" aria-label="Permalink to &quot;Risoluzione dei problemi di routine&quot;">​</a></h2><p><strong>Se hai fretta:</strong></p><ul><li>Aggiungi un respiro alla transizione</li><li>Rallenta i movimenti di installazione</li><li>Pausa prima della visualizzazione</li></ul><p><strong>Se stai pensando troppo:</strong></p><ul><li>Abbreviare la routine</li><li>Utilizzare un segnale di transizione più forte</li><li>Concentrarsi maggiormente sull&#39;esterno</li></ul><p><strong>Se sei incoerente:</strong></p><ul><li>Registrati in un video per controllare</li><li>Pratica la routine senza lanciare</li><li>Ricevi feedback da un partner</li></ul><h2 id="esempi-di-routine" tabindex="-1">Esempi di routine <a class="header-anchor" href="#esempi-di-routine" aria-label="Permalink to &quot;Esempi di routine&quot;">​</a></h2><h3 id="routine-semplice" tabindex="-1">Routine semplice <a class="header-anchor" href="#routine-semplice" aria-label="Permalink to &quot;Routine semplice&quot;">​</a></h3><ol><li>Scegli il bersaglio</li><li>Entra, respira</li><li>Afferrare, allineare</li><li>Guardalo, lancialo</li></ol><h3 id="routine-dettagliata" tabindex="-1">Routine dettagliata <a class="header-anchor" href="#routine-dettagliata" aria-label="Permalink to &quot;Routine dettagliata&quot;">​</a></h3><ol><li>Leggi il terreno, scegli il punto di atterraggio</li><li>Entrare prima con il piede sinistro</li><li>Dire &quot;liscio&quot; interiormente</li><li>Un respiro, le spalle si abbassano</li><li>Piedi posizionati, controllo della presa</li><li>Allinea le spalle al bersaglio</li><li>Guarda il percorso (2 secondi)</li><li>Gli occhi si fissano sul bersaglio</li><li>Gettare</li></ol><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>La routine è la tua ancora. Nel caos, è la tua costante.</p></blockquote><p>Costruiscilo con cura. Esercitati sempre. Fidati completamente.</p>',65))])}]]);export{d as __pageData,p as default};
